import {useState, useEffect} from 'react';

export default function Todos() {

  let [todos, setTodos] = useState([]);

  let getTodos = async () => {
    let response = await fetch('http://localhost:8080/todos/');
    let data = await response.json();
    console.log(data)
    setTodos(data);
  }

  useEffect(() => {
    getTodos();
  }, []);


  return (
    // Add todo form and list of todos

    // Form to add to new Todo
    <>
    <hr />
    <form onSubmit={async (e) => {
      e.preventDefault();
      let task = e.target.task.value;
      let response = await fetch('http://localhost:8080/todos/', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({task})
      });
      let data = await response.json();
      console.log(data);
      getTodos();
    }}>
      <input type="text" name="task" placeholder="Enter a new todo" required />
      <button type="submit">Add Todo</button>
    </form>

    <hr />
    <div>
      <h1>Todo List</h1>
      <ul>
        {todos.data && todos.data.map(todo => (
          <li key={todo._id}>{todo.task}</li>
        ))}
      </ul>
    </div>

    <hr />
    <div>
      <h1>Todo List</h1>
      <ul>
        {todos.data && todos.data.map(todo => (
          <li key={todo._id}>{todo.task}</li>
        ))}
      </ul>
    </div>

    <hr />
    <div>
      <h1>Todo List</h1>
      <ul>
        {todos.data && todos.data.map(todo => (
          <li key={todo._id}>{todo.task}</li>
        ))}
      </ul>
    </div>

    <hr />    
    <div>
      <h1>Todo List</h1>
      <ul>
        {todos.data && todos.data.map(todo => (
          <li key={todo._id}>{todo.task}</li>
        ))}
      </ul>
    </div>
    </>


  )
}
